public class ServiceRegistryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    // Two helper methods standing in for different parts of a program.
    static void moduleA() {
        ServiceRegistry.register("db", "jdbc:h2:mem:test");
    }

    static String moduleB() {
        return ServiceRegistry.lookup("db");
    }

    public static void main(String[] args) {
        ServiceRegistry.clearAll();
        check("lookup on empty registry", null, ServiceRegistry.lookup("db"));

        moduleA();
        check("entry registered in moduleA is visible in moduleB",
                "jdbc:h2:mem:test", moduleB());

        ServiceRegistry.register("cache", "redis://localhost:6379");
        check("second service registered", "redis://localhost:6379",
                ServiceRegistry.lookup("cache"));
        check("first service still there", "jdbc:h2:mem:test",
                ServiceRegistry.lookup("db"));

        ServiceRegistry.register("db", "jdbc:postgresql://prod/db");
        check("re-register overwrites", "jdbc:postgresql://prod/db",
                ServiceRegistry.lookup("db"));

        check("unknown service is null", null, ServiceRegistry.lookup("mail"));

        ServiceRegistry.clearAll();
        check("clearAll removes db", null, ServiceRegistry.lookup("db"));
        check("clearAll removes cache", null, ServiceRegistry.lookup("cache"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

